# the stray first <details> in the English head (RES-1753) is not carried into the translations
STRAY = re.compile(r'<details><summary>What do I get for €9\?</summary>.*?</details>\n(?=<style>)', re.S)
LINK_SWAP = tuple((f'href="/{p}"', f'href="/{{l}}/{p}"') for p in ("plans", "sample", "about", "refund", "privacy", "terms"))  # RES-2666: every legal and money link keeps the visitor's language

def money(s, lang):
    if lang == "nl": return re.sub(r"€(\d+)[.,](\d+)", r"€\1,\2", s)
    return re.sub(r"€(\d+)(?:[.,](\d+))?", lambda m: m.group(1) + ("," + m.group(2) if m.group(2) else "") + " €", s)

def build(lang):
    src = open(os.path.join(PUB, "landing.html"), encoding="utf-8").read()
    src = STRAY.sub("", src)
    i = 1 + LANGS.index(lang)
    out = src
    for row in sorted(SEG, key=lambda r: -len(r[0])):
        if row[0] not in out: raise SystemExit("fragment not found in landing.html: " + row[0][:70])
        out = out.replace(row[0], row[i])
    # amounts: only inside translated text, never in the URL of the Stripe Fix Pack link
    out = re.sub(r"(>|^)([^<]*€[^<]*)(?=<|$)", lambda m: m.group(1) + money(m.group(2), lang), out, flags=re.M)
    out = re.sub(r'(content|placeholder)="([^"]*€[^"]*)"', lambda m: f'{m.group(1)}="{money(m.group(2), lang)}"', out)
    out = out.replace('<html lang="en">', f'<html lang="{lang}">', 1)
    for a, b in LINK_SWAP: out = out.replace(a, b.format(l=lang))
    out = out.replace('<a class="mark" href="/">', f'<a class="mark" href="/{lang}">', 1)
    return out

if __name__ == "__main__":
    for lang in LANGS:
        open(os.path.join(PUB, f"landing.{lang}.html"), "w", encoding="utf-8").write(build(lang))
        print("wrote landing." + lang + ".html")
